constexpr int kMaxDepth = 128;
void set_nil(lua_State* L,const char* name){lua_pushnil(L);lua_setglobal(L,name);}void open_lib(lua_State* L,const char* name,lua_CFunction fn){luaL_requiref(L,name,fn,1);lua_pop(L,1);}
void push_json(lua_State* L,const JsonValue& value,int depth){if(depth>kMaxDepth)throw Error(ExitCode::lua_failure,"Lua conversion depth exceeded");if(value.is_null()){lua_pushnil(L);return;}if(value.is_bool()){lua_pushboolean(L,value.as_bool());return;}if(value.is_number()){lua_pushnumber(L,value.as_number());return;}if(value.is_string()){const auto&s=value.as_string();lua_pushlstring(L,s.data(),s.size());return;}if(value.is_array()){const auto&a=value.as_array();lua_createtable(L,(int)a.size(),0);int i=1;for(const auto&item:a){push_json(L,item,depth+1);lua_seti(L,-2,i++);}return;}const auto&o=value.as_object();lua_createtable(L,0,(int)o.size());for(const auto&[key,item]:o){push_json(L,item,depth+1);lua_setfield(L,-2,key.c_str());}}
JsonValue from_lua(lua_State* L,int idx,int depth){if(depth>kMaxDepth)throw Error(ExitCode::lua_failure,"Lua conversion depth exceeded");idx=lua_absindex(L,idx);switch(lua_type(L,idx)){case LUA_TNIL:return JsonValue(nullptr);case LUA_TBOOLEAN:return JsonValue(lua_toboolean(L,idx)!=0);case LUA_TNUMBER:{double n=lua_tonumber(L,idx);if(!std::isfinite(n))throw Error(ExitCode::lua_failure,"non-finite Lua number");return JsonValue(n);}case LUA_TSTRING:{size_t n=0;const char*s=lua_tolstring(L,idx,&n);return JsonValue(std::string(s,n));}case LUA_TTABLE:break;default:throw Error(ExitCode::lua_failure,"unsupported Lua value type");}const size_t len=lua_rawlen(L,idx);bool array=true;size_t count=0;lua_pushnil(L);while(lua_next(L,idx)!=0){++count;if(!lua_isinteger(L,-2))array=false;else{auto k=lua_tointeger(L,-2);if(k<1||(size_t)k>len)array=false;}lua_pop(L,1);}if(array&&count==len){JsonValue::array out;out.reserve(len);for(size_t i=1;i<=len;++i){lua_geti(L,idx,(lua_Integer)i);out.push_back(from_lua(L,-1,depth+1));lua_pop(L,1);}return JsonValue(std::move(out));}JsonValue::object out;lua_pushnil(L);while(lua_next(L,idx)!=0){if(lua_type(L,-2)!=LUA_TSTRING){lua_pop(L,2);throw Error(ExitCode::lua_failure,"Lua object keys must be strings");}size_t n=0;const char*key=lua_tolstring(L,-2,&n);out.emplace(std::string(key,n),from_lua(L,-1,depth+1));lua_pop(L,1);}return JsonValue(std::move(out));}
void get_config(lua_State* L,int ref){lua_rawgeti(L,LUA_REGISTRYINDEX,ref);}void get_field(lua_State* L,int ref,const char*name){get_config(L,ref);lua_getfield(L,-1,name);lua_remove(L,-2);}std::string required_string(lua_State* L,int idx,const char*what){if(lua_type(L,idx)!=LUA_TSTRING)throw Error(ExitCode::lua_failure,std::string(what)+" must be string");size_t n=0;const char*s=lua_tolstring(L,idx,&n);return{s,n};}
double optional_number(lua_State* L,int table,const char*key,double fallback){table=lua_absindex(L,table);lua_getfield(L,table,key);double result=fallback;if(!lua_isnil(L,-1)){if(!lua_isnumber(L,-1))throw Error(ExitCode::lua_failure,std::string(key)+" must be number");result=lua_tonumber(L,-1);}lua_pop(L,1);return result;}bool optional_bool(lua_State* L,int table,const char*key,bool fallback){table=lua_absindex(L,table);lua_getfield(L,table,key);bool result=fallback;if(!lua_isnil(L,-1)){if(!lua_isboolean(L,-1))throw Error(ExitCode::lua_failure,std::string(key)+" must be boolean");result=lua_toboolean(L,-1)!=0;}lua_pop(L,1);return result;}std::string optional_string(lua_State* L,int table,const char*key,std::string fallback){table=lua_absindex(L,table);lua_getfield(L,table,key);if(!lua_isnil(L,-1))fallback=required_string(L,-1,key);lua_pop(L,1);return fallback;}
void checked_call(lua_State* L,int nargs,int results,const char*where){if(lua_pcall(L,nargs,results,0)==LUA_OK)return;std::string message=lua_tostring(L,-1)?lua_tostring(L,-1):"Lua error";lua_pop(L,1);throw Error(ExitCode::lua_failure,std::string(where)+": "+message);}
