LuaAgent::LuaAgent(const std::filesystem::path& path,std::function<void(std::string_view)> sink):log_sink_(std::move(sink)){L_=luaL_newstate();if(!L_)throw Error(ExitCode::lua_failure,"cannot create Lua state");try{open_lib(L_,"_G",luaopen_base);open_lib(L_,LUA_TABLIBNAME,luaopen_table);open_lib(L_,LUA_STRLIBNAME,luaopen_string);open_lib(L_,LUA_MATHLIBNAME,luaopen_math);open_lib(L_,LUA_UTF8LIBNAME,luaopen_utf8);for(const char*name:{"io","os","package","debug","print","dofile","loadfile","load"})set_nil(L_,name);lua_pushlightuserdata(L_,this);lua_pushcclosure(L_,[](lua_State*L)->int{auto*self=static_cast<LuaAgent*>(lua_touserdata(L,lua_upvalueindex(1)));size_t n=0;const char*s=luaL_checklstring(L,1,&n);if(self&&self->log_sink_)self->log_sink_(std::string_view(s,n));return 0;},1);lua_setglobal(L_,"log");if(luaL_loadfilex(L_,path.string().c_str(),nullptr)!=LUA_OK){std::string e=lua_tostring(L_,-1)?lua_tostring(L_,-1):"unknown Lua load error";throw Error(ExitCode::lua_failure,"load config: "+e);}checked_call(L_,0,1,"execute config");if(!lua_istable(L_,-1))throw Error(ExitCode::lua_failure,"config must return a table");config_ref_=luaL_ref(L_,LUA_REGISTRYINDEX);load_typed_config();}catch(...){lua_close(L_);L_=nullptr;throw;}}
