void LuaAgent::load_typed_config(){get_field(L_,config_ref_,"model");if(lua_istable(L_,-1)){model_.path=optional_string(L_,-1,"path",model_.path.string());model_.context_size=(uint32_t)optional_number(L_,-1,"context_size",model_.context_size);model_.batch_size=(uint32_t)optional_number(L_,-1,"batch_size",model_.batch_size);model_.gpu_layers=(int)optional_number(L_,-1,"gpu_layers",0);model_.threads=(int)optional_number(L_,-1,"threads",0);}lua_pop(L_,1);if(model_.context_size<256||model_.context_size>131072||model_.batch_size<1||model_.batch_size>model_.context_size)throw Error(ExitCode::lua_failure,"invalid model config");get_field(L_,config_ref_,"generation");if(lua_istable(L_,-1)){generation_.thinking=optional_bool(L_,-1,"thinking",false);generation_.max_tokens=(uint32_t)optional_number(L_,-1,"max_tokens",768);generation_.temperature=(float)optional_number(L_,-1,"temperature",.7);generation_.top_p=(float)optional_number(L_,-1,"top_p",.95);generation_.top_k=(int)optional_number(L_,-1,"top_k",40);generation_.min_p=(float)optional_number(L_,-1,"min_p",0);generation_.repeat_penalty=(float)optional_number(L_,-1,"repeat_penalty",1);generation_.repeat_last_n=(int)optional_number(L_,-1,"repeat_last_n",64);generation_.seed=(int64_t)optional_number(L_,-1,"seed",-1);}lua_pop(L_,1);get_field(L_,config_ref_,"loop");if(lua_istable(L_,-1)){loop_.max_steps=(uint32_t)optional_number(L_,-1,"max_steps",32);loop_.max_tool_calls_per_step=(uint32_t)optional_number(L_,-1,"max_tool_calls_per_step",8);loop_.max_tool_result_bytes=(size_t)optional_number(L_,-1,"max_tool_result_bytes",65536);}lua_pop(L_,1);if(generation_.max_tokens<1||generation_.max_tokens>16384||generation_.temperature<0||generation_.temperature>5||generation_.top_p<0||generation_.top_p>1||generation_.min_p<0||generation_.min_p>1||generation_.top_k<0||generation_.top_k>100000||generation_.repeat_penalty<=0||generation_.repeat_penalty>10||generation_.repeat_last_n<0||(uint32_t)generation_.repeat_last_n>model_.context_size||loop_.max_steps<1||loop_.max_steps>256||loop_.max_tool_calls_per_step<1||loop_.max_tool_calls_per_step>64||loop_.max_tool_result_bytes<1024||loop_.max_tool_result_bytes>1048576)throw Error(ExitCode::lua_failure,"invalid generation/loop config");get_field(L_,config_ref_,"workspace");if(lua_istable(L_,-1)){workspace_policy_.default_access=optional_string(L_,-1,"default_access",workspace_policy_.default_access);workspace_policy_.follow_directory_symlinks=optional_bool(L_,-1,"follow_directory_symlinks",false);lua_getfield(L_,-1,"deny");if(lua_istable(L_,-1)){size_t n=lua_rawlen(L_,-1);for(size_t i=1;i<=n;++i){lua_geti(L_,-1,(lua_Integer)i);workspace_policy_.deny.push_back(required_string(L_,-1,"workspace.deny entry"));lua_pop(L_,1);}}lua_pop(L_,1);lua_getfield(L_,-1,"scopes");if(lua_istable(L_,-1)){size_t n=lua_rawlen(L_,-1);for(size_t i=1;i<=n;++i){lua_geti(L_,-1,(lua_Integer)i);if(!lua_istable(L_,-1))throw Error(ExitCode::lua_failure,"workspace.scopes entries must be tables");ScopeConfig scope{optional_string(L_,-1,"path",""),optional_string(L_,-1,"access","none")};if(scope.path.empty())throw Error(ExitCode::lua_failure,"workspace scope path cannot be empty");if(scope.access!="r"&&scope.access!="rw"&&scope.access!="none")throw Error(ExitCode::lua_failure,"workspace scope access must be r, rw, or none");workspace_policy_.scopes.push_back(std::move(scope));lua_pop(L_,1);}}lua_pop(L_,1);}lua_pop(L_,1);get_field(L_,config_ref_,"guardrails");if(lua_istable(L_,-1)){guardrail_policy_.profile=optional_string(L_,-1,"profile",guardrail_policy_.profile);guardrail_policy_.command_sandbox=optional_string(L_,-1,"command_sandbox",guardrail_policy_.command_sandbox);}lua_pop(L_,1);if(guardrail_policy_.profile!="review"&&guardrail_policy_.profile!="balanced"&&guardrail_policy_.profile!="autonomous")throw Error(ExitCode::lua_failure,"invalid guardrail profile");if(guardrail_policy_.command_sandbox!="strict"&&guardrail_policy_.command_sandbox!="best-effort"&&guardrail_policy_.command_sandbox!="off")throw Error(ExitCode::lua_failure,"invalid command sandbox mode");}
AgentRequest LuaAgent::before_prompt(const AgentRequest&r){get_field(L_,config_ref_,"before_prompt");if(lua_isnil(L_,-1)){lua_pop(L_,1);return r;}if(!lua_isfunction(L_,-1)){lua_pop(L_,1);throw Error(ExitCode::lua_failure,"before_prompt must be function");}push_json(L_,JsonValue(JsonValue::object{{"prompt",r.prompt},{"context",r.context},{"options",r.options}}),0);checked_call(L_,1,1,"before_prompt");auto v=from_lua(L_,-1,0);lua_pop(L_,1);if(!v.is_object())throw Error(ExitCode::lua_failure,"before_prompt must return object");AgentRequest out=r;if(auto*x=object_get(v.as_object(),"prompt");x&&x->is_string())out.prompt=x->as_string();if(auto*x=object_get(v.as_object(),"context"))out.context=*x;if(auto*x=object_get(v.as_object(),"options"))out.options=*x;return out;}
std::vector<ChatMessage>LuaAgent::build_messages(const AgentRequest&r){get_field(L_,config_ref_,"build_messages");if(lua_isnil(L_,-1)){lua_pop(L_,1);return{{"user",r.prompt}};}push_json(L_,JsonValue(JsonValue::object{{"prompt",r.prompt},{"context",r.context},{"options",r.options}}),0);checked_call(L_,1,1,"build_messages");auto v=from_lua(L_,-1,0);lua_pop(L_,1);if(!v.is_array())throw Error(ExitCode::lua_failure,"build_messages must return array");std::vector<ChatMessage>out;for(const auto&m:v.as_array()){if(!m.is_object())throw Error(ExitCode::lua_failure,"message must be object");auto*role=object_get(m.as_object(),"role");auto*content=object_get(m.as_object(),"content");if(!role||!content||!role->is_string()||!content->is_string())throw Error(ExitCode::lua_failure,"message requires role/content");out.push_back({role->as_string(),content->as_string()});}return out;}
