AgentResponse LuaAgent::after_response(const AgentResponse&r){get_field(L_,config_ref_,"after_response");if(lua_isnil(L_,-1)){lua_pop(L_,1);return r;}push_json(L_,JsonValue(JsonValue::object{{"output",r.output},{"model",r.model},{"metadata",r.metadata}}),0);checked_call(L_,1,1,"after_response");auto v=from_lua(L_,-1,0);lua_pop(L_,1);auto out=r;if(v.is_object()){if(auto*x=object_get(v.as_object(),"output");x&&x->is_string())out.output=x->as_string();if(auto*x=object_get(v.as_object(),"metadata"))out.metadata=*x;}return out;}
